window.CLASSWORK_UNITS = [{"unit":1,"title":"Health & Skills","chapters":[1,2],"terms":[{"c":1,"t":"Health","d":"A combination of physical, mental/emotional, and social well-being — not just the absence of disease.","x":0,"s":1},{"c":1,"t":"Wellness","d":"The quality of life that results from taking positive steps toward achieving your full health potential.","x":0,"s":1},{"c":1,"t":"Health Triangle","d":"A model showing the three sides of health: physical, mental/emotional, and social — all must be balanced.","x":0,"s":1},{"c":1,"t":"Lifestyle factors","d":"Personal behaviors and habits that affect your long-term health, both positively and negatively.","x":0,"s":1},{"c":1,"t":"Health literacy","d":"The ability to find, understand, evaluate, and apply health information to make responsible decisions.","x":0,"s":1},{"c":1,"t":"Heredity","d":"The passing of traits from biological parents to their children through genes.","x":0,"s":1},{"c":1,"t":"Environment","d":"All living and nonliving things around you, including your community, culture, and physical surroundings.","x":0,"s":1},{"c":1,"t":"Culture","d":"The beliefs, values, and practices shared by a group of people — a major influence on health decisions.","x":0,"s":1},{"c":1,"t":"Peers","d":"People of the same age who share similar interests; a powerful influence on teen health behavior.","x":0,"s":1},{"c":1,"t":"Risk behaviors","d":"Actions or habits that increase the likelihood of negative outcomes to one's health or others.","x":0,"s":1},{"c":1,"t":"Prevention","d":"Taking action to avoid disease, injury, and other health problems before they occur.","x":0,"s":1},{"c":1,"t":"Abstinence","d":"The deliberate decision to refrain from a risky behavior.","x":0,"s":1},{"c":1,"t":"Health promotion","d":"The process of enabling people to increase control over and improve their health.","x":0,"s":1},{"c":1,"t":"Protective factors","d":"Conditions or attributes that reduce the impact of risk factors on health outcomes.","x":0,"s":1},{"c":1,"t":"Attitude","d":"A feeling or disposition toward a person, object, or idea that influences behavior.","x":0,"s":1},{"c":1,"t":"Spiritual health","d":"A deep-seated sense of meaning and purpose in life.","x":0,"s":1},{"c":1,"t":"Chronic disease","d":"An ongoing condition or illness such as heart disease, obesity, or cancer.","x":0,"s":1},{"c":1,"t":"Media","d":"The various methods for communicating information.","x":0,"s":1},{"c":1,"t":"Technology","d":"The tools and methods used to deliver media content.","x":0,"s":1},{"c":1,"t":"Cumulative risks","d":"Related risks that increase in effect with each added risk.","x":0,"s":1},{"c":1,"t":"Health education","d":"Providing accurate health information and teaching health skills to help people make healthy decisions.","x":0,"s":1},{"c":1,"t":"Healthy People 2030","d":"A nationwide health promotion and disease prevention plan with goals set for the current decade.","x":0,"s":1},{"c":1,"t":"Health disparities","d":"Differences in health outcomes among groups based on gender, race, education, disability, or location.","x":0,"s":1},{"c":2,"t":"Goal setting","d":"The process of identifying something you want to accomplish and creating a plan to achieve it.","x":0,"s":1},{"c":2,"t":"SMART goals","d":"Goals that are Specific, Measurable, Achievable, Realistic, and Time-bound.","x":0,"s":1},{"c":2,"t":"Decision making","d":"A five-step process for making healthy, responsible choices.","x":0,"s":1},{"c":2,"t":"Values","d":"The beliefs and principles that guide your behavior and decisions.","x":0,"s":1},{"c":2,"t":"Refusal skills","d":"Strategies that help you say no to things that are harmful or illegal.","x":0,"s":1},{"c":2,"t":"Conflict resolution","d":"A process for resolving disagreements in a peaceful, constructive way.","x":0,"s":1},{"c":2,"t":"Stress management","d":"Techniques for controlling and reducing the physical and emotional effects of stress.","x":0,"s":1},{"c":2,"t":"Communication skills","d":"The ability to share information clearly with others using listening, speaking, and body language.","x":0,"s":1},{"c":2,"t":"Self-management","d":"The ability to control your emotions, behaviors, and actions to make healthy choices.","x":0,"s":1},{"c":2,"t":"Advocacy","d":"Taking action to promote health and influence others to make positive choices.","x":0,"s":1},{"c":2,"t":"Accessing information","d":"The skill of finding and evaluating reliable, accurate health information from valid sources.","x":0,"s":1},{"c":2,"t":"Analyzing influences","d":"The ability to identify and examine the factors that affect health beliefs and behaviors.","x":0,"s":1},{"c":2,"t":"Health skills","d":"Specific tools and strategies to maintain, protect, and improve all aspects of your health; also called life skills.","x":0,"s":1},{"c":2,"t":"Interpersonal communication","d":"The exchange of thoughts, feelings, and beliefs between two or more people.","x":0,"s":1},{"c":2,"t":"Stress","d":"The reaction of the body and mind to everyday challenges and demands.","x":0,"s":1},{"c":2,"t":"Decision-making skills","d":"Steps that enable you to make a healthful decision.","x":0,"s":1},{"c":2,"t":"Goals","d":"Things you aim for that take planning and work.","x":0,"s":1},{"c":2,"t":"Short-term goal","d":"A goal you can reach in a short period of time.","x":0,"s":1},{"c":2,"t":"Long-term goal","d":"A goal you plan to reach over an extended period of time.","x":0,"s":1},{"c":2,"t":"Action plan","d":"A multistep strategy to identify and achieve your goals.","x":0,"s":1},{"c":2,"t":"Health consumer","d":"Someone who purchases or uses health products or services.","x":0,"s":1},{"c":2,"t":"Advertising","d":"A written or spoken media message designed to interest consumers in purchasing a product or service.","x":0,"s":1},{"c":2,"t":"Comparison shopping","d":"Judging the benefits of different products by comparing factors such as quality, features, and cost.","x":0,"s":1},{"c":2,"t":"Warranty","d":"A company's or store's written agreement to repair a product or refund your money if it does not function properly.","x":0,"s":1},{"c":2,"t":"Consumer advocates","d":"People or groups whose purpose is to take on consumer issues and inform the public about potential problems.","x":0,"s":1},{"c":2,"t":"Malpractice","d":"Failure by a health professional to meet accepted standards of care.","x":0,"s":1},{"c":2,"t":"Health fraud","d":"The sale of worthless products or services that claim to prevent disease or cure health problems; also called quackery.","x":0,"s":1}]},{"unit":2,"title":"Mental & Emotional Health","chapters":[3,4,5],"terms":[{"c":3,"t":"Mental health","d":"The state of your psychological and emotional well-being — how you think, feel, and cope with life.","x":0,"s":1},{"c":3,"t":"Emotions","d":"Signals that tell your mind and body how to react to situations.","x":0,"s":1},{"c":3,"t":"Self-concept","d":"The view you have of yourself — your strengths, weaknesses, thoughts, and feelings.","x":0,"s":1},{"c":3,"t":"Self-esteem","d":"The confidence and satisfaction you have in yourself and your own abilities.","x":0,"s":1},{"c":3,"t":"Empathy","d":"The ability to understand and share the feelings of another person.","x":0,"s":1},{"c":3,"t":"Emotional intelligence","d":"The ability to recognize, understand, and manage your own emotions and recognize emotions in others.","x":0,"s":1},{"c":3,"t":"Resiliency","d":"The ability to recover from setbacks, adapt to change, and keep going in the face of adversity.","x":0,"s":1},{"c":3,"t":"Grief","d":"The emotional response to loss — a normal and necessary process that takes time.","x":0,"s":1},{"c":3,"t":"Coping strategies","d":"Healthy ways of managing and reducing the emotional pain of difficult situations.","x":0,"s":1},{"c":3,"t":"Defense mechanisms","d":"Unconscious mental strategies used to protect yourself from uncomfortable emotions.","x":0,"s":1},{"c":3,"t":"Positive affirmations","d":"Statements that remind you of your strengths and help reinforce a positive self-image.","x":0,"s":1},{"c":3,"t":"Mindfulness","d":"The practice of focusing attention on the present moment with openness and without judgment.","x":0,"s":1},{"c":3,"t":"Mental/emotional health","d":"The ability to accept yourself and others, express and manage emotions, and deal with the demands and challenges of life.","x":0,"s":1},{"c":3,"t":"Competence","d":"Having enough skills to do something successfully.","x":0,"s":1},{"c":3,"t":"Hierarchy of needs","d":"A ranked list of needs essential to human growth and development, from basic physical needs up to reaching your full potential.","x":0,"s":1},{"c":3,"t":"Self-actualization","d":"The drive to reach your full potential and become the best version of yourself.","x":0,"s":1},{"c":3,"t":"Personal identity","d":"Your sense of yourself as a unique individual, shaped by your values, relationships, experiences, and beliefs.","x":0,"s":1},{"c":3,"t":"Role model","d":"Someone whose success or behavior serves as an example for others.","x":0,"s":1},{"c":3,"t":"Personality","d":"The complex set of characteristics that makes a person unique.","x":0,"s":1},{"c":3,"t":"Character","d":"The distinctive qualities that describe how a person thinks, feels, and behaves.","x":0,"s":1},{"c":3,"t":"Integrity","d":"A firm, consistent commitment to core ethical values.","x":0,"s":1},{"c":3,"t":"Constructive criticism","d":"Honest, non-hostile feedback that points out problems and encourages improvement.","x":0,"s":1},{"c":3,"t":"Hormones","d":"Chemicals produced by your glands that regulate the activities of different body cells.","x":0,"s":1},{"c":3,"t":"Hostility","d":"The intentional use of unfriendly or offensive behavior toward others.","x":0,"s":1},{"c":4,"t":"Stress","d":"The body's and mind's reaction to everyday demands and threats, real or perceived.","x":0,"s":1},{"c":4,"t":"Stressor","d":"Any situation, event, or person that causes stress.","x":0,"s":1},{"c":4,"t":"Fight-or-flight response","d":"The body's automatic physiological reaction to a perceived threat — prepares to fight or flee.","x":0,"s":1},{"c":4,"t":"Adrenaline","d":"The hormone released during stress that increases heart rate, blood pressure, and energy.","x":0,"s":1},{"c":4,"t":"Eustress","d":"Positive stress that motivates and energizes, such as excitement before a sports event.","x":0,"s":1},{"c":4,"t":"Distress","d":"Negative stress that feels overwhelming and harmful to health.","x":0,"s":1},{"c":4,"t":"Chronic stress","d":"Ongoing, long-term stress that persists over weeks or months and damages health.","x":0,"s":1},{"c":4,"t":"Relaxation response","d":"The body's ability to slow down and recover after a stressful event.","x":0,"s":1},{"c":4,"t":"Time management","d":"The practice of organizing and prioritizing tasks to reduce stress and increase productivity.","x":0,"s":1},{"c":4,"t":"Support network","d":"Friends, family, and others who provide emotional encouragement and practical help.","x":0,"s":1},{"c":4,"t":"Burnout","d":"A state of physical and emotional exhaustion from prolonged, unmanaged stress.","x":0,"s":1},{"c":4,"t":"Cortisol","d":"The primary stress hormone; sustained high levels damage the immune system and cardiovascular health.","x":0,"s":1},{"c":4,"t":"General Adaptation Syndrome","d":"The three-stage process (alarm, resistance, exhaustion) the body goes through when exposed to prolonged stress.","x":0,"s":1},{"c":4,"t":"Resilience","d":"The ability to recover from stress, trauma, and adversity.","x":0,"s":1},{"c":4,"t":"Acute stress","d":"Short-term, intense stress that passes once the event ends.","x":0,"s":1},{"c":4,"t":"Alarm stage","d":"The first stage of the General Adaptation Syndrome, when the body detects a stressor and triggers fight-or-flight.","x":0,"s":1},{"c":4,"t":"Exhaustion stage","d":"The final stage of the General Adaptation Syndrome, when long stress uses up the body's reserves and illness becomes more likely.","x":0,"s":1},{"c":4,"t":"Reframing","d":"Changing how you interpret a stressor.","x":0,"s":1},{"c":4,"t":"Post-traumatic growth","d":"Developing greater strength, deeper relationships and clearer priorities after a very difficult experience.","x":0,"s":1},{"c":4,"t":"Progressive muscle relaxation","d":"A stress technique of tensing and then relaxing muscle groups one at a time.","x":0,"s":1},{"c":4,"t":"Perception","d":"The way you see, understand and interpret a situation.","x":1,"s":1},{"c":4,"t":"Psychosomatic Response","d":"A physical reaction, like a headache or upset stomach, caused by stress or emotions instead of an injury or illness.","x":1,"s":1},{"c":4,"t":"Coping","d":"Dealing successfully with difficult changes or problems in your life.","x":1,"s":1},{"c":5,"t":"Mental disorder","d":"An illness that affects a person's thinking, feeling, or behavior significantly enough to cause distress.","x":0,"s":1},{"c":5,"t":"Anxiety disorder","d":"A category of mental health conditions characterized by excessive, persistent fear or worry.","x":0,"s":1},{"c":5,"t":"Depression","d":"A mood disorder marked by persistent sadness, hopelessness, loss of interest, and low energy.","x":0,"s":1},{"c":5,"t":"Suicide","d":"The act of intentionally ending one's own life — a preventable public health crisis.","x":0,"s":0},{"c":5,"t":"Suicide prevention","d":"Strategies and actions to recognize warning signs and connect people to help before a crisis.","x":0,"s":0},{"c":5,"t":"Eating disorder","d":"A serious mental illness involving extreme disturbances in eating behavior and body image.","x":0,"s":0},{"c":5,"t":"Anorexia nervosa","d":"An eating disorder involving severe restriction of food intake driven by fear of weight gain.","x":0,"s":0},{"c":5,"t":"Bulimia nervosa","d":"An eating disorder involving cycles of binge eating followed by purging behaviors.","x":0,"s":0},{"c":5,"t":"PTSD","d":"Post-Traumatic Stress Disorder — a mental health condition triggered by experiencing or witnessing trauma.","x":0,"s":0},{"c":5,"t":"Therapy","d":"Treatment by a trained mental health professional using evidence-based psychological methods.","x":0,"s":1},{"c":5,"t":"Psychiatry","d":"A branch of medicine focused on diagnosing, treating, and preventing mental disorders.","x":0,"s":1},{"c":5,"t":"Stigma","d":"Negative attitudes or discrimination against people with mental health conditions — a major barrier to seeking help.","x":0,"s":1},{"c":5,"t":"Phobia","d":"An intense, irrational fear of a specific object or situation.","x":0,"s":1},{"c":5,"t":"ADHD","d":"Attention-deficit/hyperactivity disorder; difficulty sustaining attention and controlling impulses.","x":0,"s":1},{"c":5,"t":"Obsessive-compulsive disorder (OCD)","d":"A disorder involving recurring, unwanted thoughts and repetitive behaviors.","x":0,"s":1},{"c":5,"t":"Panic disorder","d":"An anxiety disorder with repeated, sudden attacks of intense fear and physical symptoms like a racing heart.","x":0,"s":1},{"c":5,"t":"Social anxiety","d":"Intense fear of being judged or embarrassed in social situations.","x":0,"s":1},{"c":5,"t":"Psychiatrist","d":"A medical doctor who can diagnose mental disorders and prescribe medication.","x":0,"s":1},{"c":5,"t":"Therapist","d":"A professional who provides talk therapy to help people understand and change thought and behavior patterns.","x":0,"s":1},{"c":5,"t":"Crisis line","d":"A free, confidential phone or text service for people in crisis, such as 988, open 24/7.","x":0,"s":0},{"c":5,"t":"Apathy","d":"A lack of strong feeling, interest or concern about things.","x":1,"s":1},{"c":5,"t":"Alienation","d":"Feeling isolated and separated from everyone else.","x":1,"s":1},{"c":5,"t":"Cognitive Therapy","d":"Therapy that helps a person notice and change negative or unhelpful ways of thinking.","x":1,"s":1}]},{"unit":3,"title":"Relationships","chapters":[6,7,8,9],"terms":[{"c":6,"t":"Relationship","d":"A bond or connection between people based on shared experiences, trust, and mutual care.","x":0,"s":1},{"c":6,"t":"Communication","d":"The process of sharing information, thoughts, and feelings using verbal and nonverbal methods.","x":0,"s":1},{"c":6,"t":"Active listening","d":"Fully concentrating on what someone is saying, showing you understand, and responding thoughtfully.","x":0,"s":1},{"c":6,"t":"Assertiveness","d":"The ability to express your thoughts and feelings confidently and respectfully, without aggression.","x":0,"s":1},{"c":6,"t":"Boundary","d":"A limit you set to protect your physical, emotional, and mental well-being in relationships.","x":0,"s":1},{"c":6,"t":"Trust","d":"The firm belief in the reliability, truth, or ability of another person — the foundation of healthy relationships.","x":0,"s":1},{"c":6,"t":"Respect","d":"Treating others with consideration for their feelings, rights, and boundaries.","x":0,"s":1},{"c":6,"t":"Reciprocity","d":"The mutual exchange of benefits, care, or support between people in a healthy relationship.","x":0,"s":1},{"c":6,"t":"Jealousy","d":"A feeling of insecurity or fear of losing something or someone to another — can damage relationships.","x":0,"s":1},{"c":6,"t":"Healthy relationship","d":"A relationship built on trust, respect, communication, equality, and support for each other's goals.","x":0,"s":1},{"c":6,"t":"I statements","d":"Phrases that express personal feelings without blaming others, beginning with \"I feel...\".","x":0,"s":1},{"c":6,"t":"Peer pressure","d":"Influence from people your own age to act or think in a certain way.","x":0,"s":1},{"c":6,"t":"Refusal skills","d":"Strategies used to say no to unwanted or risky behaviors.","x":0,"s":1},{"c":6,"t":"Boundaries","d":"Limits a person sets on what they consider acceptable behavior from others.","x":0,"s":1},{"c":6,"t":"Manipulation","d":"Using unfair or dishonest methods to control or influence another person.","x":0,"s":1},{"c":6,"t":"Passive communication","d":"Avoiding conflict by not expressing your needs, which builds resentment.","x":0,"s":1},{"c":6,"t":"Aggressive communication","d":"Expressing needs in a hostile or blaming way that can win arguments but damages trust.","x":0,"s":1},{"c":6,"t":"Nonverbal communication","d":"Messages sent without words, such as eye contact, posture and tone of voice.","x":0,"s":1},{"c":6,"t":"Broken record technique","d":"A refusal strategy of calmly repeating no.","x":0,"s":1},{"c":6,"t":"Delay tactic","d":"A refusal strategy that buys time, such as saying \"I need to think about it.\".","x":0,"s":1},{"c":6,"t":"Compromise","d":"A solution where each person gives up something to reach an agreement that works for everyone.","x":1,"s":1},{"c":6,"t":"Stereotype","d":"An exaggerated or oversimplified belief about people who belong to a certain group.","x":1,"s":1},{"c":6,"t":"Body Language","d":"Messages you send with your posture, gestures, facial expressions and eye contact.","x":1,"s":1},{"c":7,"t":"Siblings","d":"Brothers and sisters.","x":0,"s":1},{"c":7,"t":"Nuclear family","d":"Two parents and one or more children living in the same home.","x":0,"s":1},{"c":7,"t":"Blended family","d":"A family formed when a single parent remarries, bringing together children from previous relationships.","x":0,"s":1},{"c":7,"t":"Extended family","d":"A family that includes relatives beyond parents and children, such as grandparents, aunts, uncles and cousins.","x":0,"s":1},{"c":7,"t":"Foster care","d":"The temporary placement of children in the homes of adults who are not related to them.","x":0,"s":1},{"c":7,"t":"Affirmation","d":"Positive feedback that helps others feel appreciated and supported.","x":0,"s":1},{"c":7,"t":"Separation","d":"A decision by two married people to live apart from each other.","x":0,"s":1},{"c":7,"t":"Divorce","d":"A legal end to a marriage contract.","x":0,"s":1},{"c":7,"t":"Custody","d":"The legal right to make decisions affecting children and the responsibility for their care.","x":0,"s":1},{"c":7,"t":"Abuse","d":"The physical, mental, emotional, or sexual mistreatment of one person by another.","x":0,"s":0},{"c":7,"t":"Domestic violence","d":"Acts of violence or abuse involving family members.","x":0,"s":0},{"c":7,"t":"Spousal abuse","d":"Domestic violence or abuse directed at a spouse or partner.","x":0,"s":0},{"c":7,"t":"Child abuse","d":"Domestic abuse directed at a child, including physical, emotional, or sexual harm.","x":0,"s":0},{"c":7,"t":"Neglect","d":"The failure to provide for a child's basic needs.","x":0,"s":0},{"c":7,"t":"Elder abuse","d":"The abuse or neglect of older family members.","x":0,"s":0},{"c":7,"t":"Cycle of violence","d":"The pattern of repeating violent or abusive behaviors from one generation to the next.","x":0,"s":0},{"c":7,"t":"Crisis center","d":"A facility that offers advice and support to people dealing with personal emergencies.","x":0,"s":0},{"c":7,"t":"Adoption","d":"Becoming a permanent legal family for a child.","x":0,"s":1},{"c":7,"t":"Single-parent family","d":"One parent raising one or more children, often after divorce, separation or death.","x":0,"s":1},{"c":7,"t":"Commitment","d":"Making time for family members and working on problems together.","x":0,"s":1},{"c":8,"t":"Peers","d":"People your age who share similar interests.","x":0,"s":1},{"c":8,"t":"Platonic friendship","d":"A friendship with someone of a different gender involving genuine affection, but without romantic involvement.","x":0,"s":1},{"c":8,"t":"Clique","d":"A small circle of friends who exclude people viewed as outsiders.","x":0,"s":1},{"c":8,"t":"Harassment","d":"Persistently annoying or targeting others through hurtful behaviors like name-calling, teasing, or bullying.","x":0,"s":1},{"c":8,"t":"Priorities","d":"The goals, tasks, values, and activities you judge to be most important.","x":0,"s":1},{"c":8,"t":"Intimacy","d":"A closeness between two people that develops over time through genuine connection and trust.","x":0,"s":0},{"c":8,"t":"Infatuation","d":"Exaggerated feelings of intense passion that can feel overwhelming but are often short-lived.","x":0,"s":1},{"c":8,"t":"Abstinence","d":"A deliberate decision to avoid high-risk behaviors, including sexual activity and the use of alcohol, tobacco, and other drugs.","x":0,"s":1},{"c":8,"t":"Self-control","d":"The ability to use responsibility and values to override emotions in the moment.","x":0,"s":1},{"c":8,"t":"Sexually transmitted infections (STIs)","d":"Infectious diseases spread from person to person through sexual contact.","x":0,"s":0},{"c":8,"t":"Casual friendship","d":"A friendship built on shared interests without deep emotional bonds.","x":0,"s":1},{"c":8,"t":"Close friendship","d":"A friendship with deep emotional ties, where you can share thoughts and struggles without judgment.","x":0,"s":1},{"c":8,"t":"Positive peer pressure","d":"Influence from peers that pushes you to try new activities, work harder or avoid risky behavior.","x":0,"s":1},{"c":8,"t":"State your position","d":"The first refusal step: say no clearly and firmly, with an honest reason.","x":0,"s":1},{"c":8,"t":"Suggest alternatives","d":"The second refusal step: offer another activity so you stay connected without giving up your values.","x":0,"s":1},{"c":8,"t":"Stand your ground","d":"The third refusal step: make it clear you won't budge, and walk away if needed.","x":0,"s":1},{"c":8,"t":"Online safety","d":"Habits that protect you online, like keeping personal details private and never meeting an online contact alone.","x":0,"s":1},{"c":9,"t":"Conflict","d":"Any disagreement, struggle, or fight.","x":0,"s":1},{"c":9,"t":"Interpersonal conflicts","d":"Conflicts between two or more people or groups.","x":0,"s":1},{"c":9,"t":"Escalate","d":"To become more serious or intense.","x":0,"s":1},{"c":9,"t":"Negotiation","d":"The use of communication and compromise to settle a disagreement.","x":0,"s":1},{"c":9,"t":"Mediation","d":"Bringing in a neutral third party to help others resolve their conflicts peacefully.","x":0,"s":1},{"c":9,"t":"Confidentiality","d":"Respecting the privacy of both parties and keeping details of a discussion secret.","x":0,"s":1},{"c":9,"t":"Peer mediation","d":"A process in which specially trained students help other students resolve conflicts peacefully.","x":0,"s":1},{"c":9,"t":"Violence","d":"The threatened or actual use of physical force or power to harm another person or damage property.","x":0,"s":1},{"c":9,"t":"Assault","d":"An unlawful physical attack or threat of attack.","x":0,"s":0},{"c":9,"t":"Random violence","d":"Violence committed for no particular reason against an unrelated victim.","x":0,"s":1},{"c":9,"t":"Homicide","d":"The willful killing of one human being by another.","x":0,"s":0},{"c":9,"t":"Sexual violence","d":"Any form of unwelcome sexual contact directed at an individual.","x":0,"s":0},{"c":9,"t":"Bullying","d":"Repeated, deliberate hurtful behavior by someone who has more power than the target.","x":0,"s":1},{"c":9,"t":"Cyberbullying","d":"Bullying that happens through phones, social media, games, or other technology.","x":0,"s":1},{"c":9,"t":"Physical abuse","d":"A pattern of intentionally causing bodily harm or injury to another person.","x":0,"s":0},{"c":9,"t":"Emotional abuse","d":"A pattern of attacking another person's emotional development and sense of worth.","x":0,"s":0},{"c":9,"t":"Verbal abuse","d":"The use of words to mistreat or injure another person; a form of emotional abuse.","x":0,"s":0},{"c":9,"t":"Stalking","d":"Repeatedly following, harassing, or threatening an individual in person or online.","x":0,"s":0},{"c":9,"t":"Upstander","d":"Someone who speaks up, supports the target or gets help when they see bullying.","x":0,"s":1},{"c":9,"t":"Hate crime","d":"A crime motivated by hatred of a group because of race, religion, disability, sexual orientation or other traits.","x":0,"s":0}]},{"unit":4,"title":"Nutrition, Weight & Exercise","chapters":[10,11,12],"terms":[{"c":10,"t":"Nutrients","d":"Substances in food that provide energy and materials the body needs to grow, repair, and function.","x":0,"s":1},{"c":10,"t":"Carbohydrates","d":"The body's primary energy source; should make up 45–65% of daily calories.","x":0,"s":1},{"c":10,"t":"Proteins","d":"Nutrients that build and repair cells, muscles, and tissues; made of amino acids.","x":0,"s":1},{"c":10,"t":"Fats","d":"Nutrients that store energy, protect organs, and support vitamin absorption; essential in moderation.","x":0,"s":1},{"c":10,"t":"Vitamins","d":"Organic compounds needed in small amounts to regulate body functions and prevent disease.","x":0,"s":1},{"c":10,"t":"Minerals","d":"Inorganic substances (calcium, iron, zinc) essential for bone health, blood, and body functions.","x":0,"s":1},{"c":10,"t":"MyPlate","d":"The USDA visual guide showing the five food groups and recommended proportions for healthy eating.","x":0,"s":1},{"c":10,"t":"Calorie","d":"A unit of energy; the amount of energy in food that the body uses to perform functions.","x":0,"s":1},{"c":10,"t":"Dietary fiber","d":"Indigestible plant material that supports digestive health, lowers cholesterol, and controls blood sugar.","x":0,"s":1},{"c":10,"t":"Saturated fat","d":"A type of fat found in animal products that raises LDL (bad) cholesterol when consumed in excess.","x":0,"s":1},{"c":10,"t":"Trans fat","d":"An artificially created fat that raises bad cholesterol and lowers good cholesterol — largely banned.","x":0,"s":1},{"c":10,"t":"Nutrition label","d":"The panel on food packaging showing calorie count, nutrients, and percent daily values.","x":0,"s":1},{"c":10,"t":"Dietary guidelines","d":"Science-based advice from the USDA and HHS on what to eat and drink to promote health.","x":0,"s":1},{"c":10,"t":"Fiber","d":"A type of carbohydrate the body cannot digest; promotes digestive health and reduces disease risk.","x":0,"s":1},{"c":10,"t":"Unsaturated fat","d":"A healthier type of fat, found in foods like nuts, fish and olive oil, that should replace saturated and trans fats.","x":0,"s":1},{"c":10,"t":"Added sugars","d":"Sugars put into foods during processing; the Dietary Guidelines say to keep them under 10% of daily calories.","x":0,"s":1},{"c":10,"t":"Sodium","d":"A mineral found in salt; the Dietary Guidelines say to keep it under 2,300 mg per day.","x":0,"s":1},{"c":10,"t":"Serving size","d":"The amount of food that all the numbers on a Nutrition Facts label are based on.","x":0,"s":1},{"c":10,"t":"Percent Daily Value","d":"How much a serving adds to a day's needs; 5% or less is low and 20% or more is high.","x":0,"s":1},{"c":10,"t":"Ultra-processed foods","d":"Packaged foods like chips and fast food that are engineered to override your hunger signals.","x":0,"s":1},{"c":10,"t":"Appetite","d":"A desire to eat that comes from emotions or the look and smell of food, not physical need.","x":1,"s":1},{"c":10,"t":"Nutrient-Dense","d":"Foods with a lot of nutrients compared with the number of calories they have.","x":1,"s":1},{"c":10,"t":"Cross-Contamination","d":"The spread of bacteria or other germs from one food or surface to another.","x":1,"s":1},{"c":11,"t":"Body Mass Index (BMI)","d":"A ratio of weight to height used as a screening tool for healthy weight — not a diagnosis.","x":0,"s":1},{"c":11,"t":"Metabolism","d":"The rate at which your body converts food into energy — affects weight management.","x":0,"s":1},{"c":11,"t":"Basal metabolic rate","d":"The number of calories your body needs to maintain basic functions at rest.","x":0,"s":1},{"c":11,"t":"Caloric balance","d":"The relationship between calories consumed and calories burned through activity.","x":0,"s":1},{"c":11,"t":"Body image","d":"The way you see and feel about your physical appearance.","x":0,"s":1},{"c":11,"t":"Eating disorder","d":"A serious mental illness with extreme disturbances in eating behavior, body image, and weight.","x":0,"s":0},{"c":11,"t":"Anorexia nervosa","d":"An eating disorder involving extreme restriction of food intake driven by fear of weight gain.","x":0,"s":0},{"c":11,"t":"Bulimia nervosa","d":"An eating disorder with cycles of binge eating followed by purging.","x":0,"s":0},{"c":11,"t":"Binge eating disorder","d":"Recurrent episodes of eating large amounts of food rapidly without purging — most common ED.","x":0,"s":0},{"c":11,"t":"Fad diet","d":"A popular diet promising quick weight loss that typically lacks scientific support and is unsustainable.","x":0,"s":1},{"c":11,"t":"Weight management","d":"A long-term approach to maintaining a healthy weight through balanced nutrition and physical activity.","x":0,"s":1},{"c":11,"t":"Obesity","d":"A condition of excess body fat that increases risk of diabetes, heart disease, and other conditions.","x":0,"s":1},{"c":11,"t":"Body composition","d":"The ratio of fat mass to lean (muscle, bone, water) mass in the body.","x":0,"s":1},{"c":11,"t":"Intuitive eating","d":"An approach to food that honors internal hunger and fullness cues rather than external diet rules.","x":0,"s":1},{"c":11,"t":"Mindful eating","d":"Paying attention to hunger and fullness cues and avoiding emotional eating.","x":0,"s":1},{"c":11,"t":"Emotional eating","d":"Eating in response to feelings rather than hunger.","x":0,"s":1},{"c":11,"t":"Orthorexia","d":"An obsessive focus on \"clean\" or \"pure\" eating to the point of harm.","x":0,"s":0},{"c":11,"t":"All Foods Fit","d":"The idea that balance, variety and moderation matter more than labeling foods good or bad.","x":0,"s":1},{"c":11,"t":"Underweight","d":"A BMI below 18.5, which may signal a nutritional deficiency or eating disorder.","x":0,"s":1},{"c":11,"t":"Overweight","d":"A BMI of 25–29.9, linked to increased risk for chronic conditions.","x":0,"s":1},{"c":11,"t":"Weight Cycling","d":"Repeatedly losing and then regaining weight.","x":1,"s":1},{"c":11,"t":"Dietary Supplements","d":"Pills, powders or liquids taken to add nutrients to your diet.","x":1,"s":1},{"c":11,"t":"Performance Enhancers","d":"Substances taken to try to improve athletic performance, many of them unsafe.","x":1,"s":1},{"c":12,"t":"Physical activity","d":"Any movement that uses energy — from walking to organized sports.","x":0,"s":1},{"c":12,"t":"Exercise","d":"Planned, structured, repetitive physical activity done to improve or maintain fitness.","x":0,"s":1},{"c":12,"t":"Aerobic exercise","d":"Sustained activity that increases heart and breathing rate — improves cardiovascular fitness.","x":0,"s":1},{"c":12,"t":"Anaerobic exercise","d":"Short, intense bursts of activity that don't rely on oxygen — builds strength and power.","x":0,"s":1},{"c":12,"t":"Flexibility","d":"The range of motion available at a joint — maintained through stretching.","x":0,"s":1},{"c":12,"t":"Muscle strength","d":"The maximum force a muscle or muscle group can exert in a single effort.","x":0,"s":1},{"c":12,"t":"Muscle endurance","d":"The ability of a muscle to perform repeated contractions over time without fatigue.","x":0,"s":1},{"c":12,"t":"Cardiovascular endurance","d":"The ability of the heart and lungs to supply oxygen during sustained physical activity.","x":0,"s":1},{"c":12,"t":"FITT principle","d":"Frequency, Intensity, Time, and Type — the four variables used to design an effective workout.","x":0,"s":1},{"c":12,"t":"Overload principle","d":"To improve fitness, you must gradually increase the demand placed on the body.","x":0,"s":1},{"c":12,"t":"Warm-up","d":"Low-intensity activity before exercise that prepares muscles and reduces injury risk.","x":0,"s":1},{"c":12,"t":"Cool-down","d":"Low-intensity activity after exercise that gradually returns the body to its resting state.","x":0,"s":1},{"c":12,"t":"Physical fitness","d":"The ability to carry out daily tasks with vigor and without undue fatigue.","x":0,"s":1},{"c":12,"t":"Skill-related fitness","d":"Fitness components important for sports and daily movement: agility, balance, coordination, power, reaction time and speed.","x":0,"s":1},{"c":12,"t":"Agility","d":"The ability to change direction quickly while keeping control.","x":0,"s":1},{"c":12,"t":"Balance","d":"The ability to stay steady and upright, whether still or moving.","x":0,"s":1},{"c":12,"t":"Coordination","d":"The ability to use body parts together smoothly.","x":0,"s":1},{"c":12,"t":"Reaction time","d":"How quickly you respond to a signal, like a starting gun.","x":0,"s":1},{"c":12,"t":"RICE","d":"Rest, Ice, Compression, Elevation: first steps for sprains, strains and minor injuries.","x":0,"s":1},{"c":12,"t":"Overtraining","d":"Training too much without enough rest, which leads to fatigue and injury.","x":0,"s":1},{"c":12,"t":"Sedentary","d":"Spending most of the day sitting or inactive.","x":1,"s":1},{"c":12,"t":"Resting Heart Rate","d":"How many times your heart beats per minute while you are at rest.","x":1,"s":1},{"c":12,"t":"Sprain","d":"An injury where a ligament at a joint is stretched or torn.","x":1,"s":1}]},{"unit":5,"title":"Your Body","chapters":[13,14,15,16],"terms":[{"c":13,"t":"Epidermis","d":"The outer, thinner layer of skin composed of living and dead cells.","x":0,"s":1},{"c":13,"t":"Dermis","d":"The thicker inner layer of skin containing blood vessels, nerves, and glands.","x":0,"s":1},{"c":13,"t":"Melanin","d":"The pigment that gives skin, hair, and eyes their color and provides some UV protection.","x":0,"s":1},{"c":13,"t":"Sebaceous glands","d":"Structures in the dermis that produce sebum — an oily secretion that moisturizes skin and hair.","x":0,"s":1},{"c":13,"t":"Melanoma","d":"The most serious and potentially fatal form of skin cancer — detected using the ABCDE rule.","x":0,"s":1},{"c":13,"t":"Periodontium","d":"The structures immediately surrounding a tooth, including the gum, ligaments, and jawbone.","x":0,"s":1},{"c":13,"t":"Plaque","d":"A sticky film of bacteria and food particles on teeth that produces acids causing decay.","x":0,"s":1},{"c":13,"t":"Halitosis","d":"Bad breath caused by food, poor oral hygiene, bacteria, or gum disease.","x":0,"s":1},{"c":13,"t":"Periodontal disease","d":"Inflammation and infection of the gum and supporting structures of the teeth.","x":0,"s":1},{"c":13,"t":"Sclera","d":"The tough white outer layer of the eye.","x":0,"s":1},{"c":13,"t":"Retina","d":"The inner layer of the eye containing light-sensitive rods and cones.","x":0,"s":1},{"c":13,"t":"Tinnitus","d":"A ringing, buzzing, or hissing sound in the ear with no external source — warning sign of hearing damage.","x":0,"s":1},{"c":13,"t":"Hygiene","d":"Practices that maintain cleanliness and prevent disease.","x":0,"s":1},{"c":13,"t":"Dermatologist","d":"A doctor who specializes in skin, hair, and nail conditions.","x":0,"s":1},{"c":13,"t":"Fluoride","d":"A mineral that strengthens tooth enamel and helps prevent decay.","x":0,"s":1},{"c":13,"t":"Preventive care","d":"Health services aimed at preventing disease before it occurs, including checkups and vaccinations.","x":0,"s":1},{"c":13,"t":"Immunization","d":"Protection from disease through vaccines that stimulate the immune system.","x":0,"s":1},{"c":13,"t":"Consumer health","d":"The evaluation of products, services, and information related to health.","x":0,"s":1},{"c":13,"t":"OTC medication","d":"Over-the-counter drugs available without a prescription.","x":0,"s":1},{"c":13,"t":"SPF","d":"Sun Protection Factor — a measure of how well sunscreen blocks UV radiation.","x":0,"s":1},{"c":13,"t":"Acne","d":"A skin condition caused by clogged pores resulting in pimples, blackheads, and whiteheads.","x":0,"s":1},{"c":13,"t":"Cornea","d":"The clear front part of the eye that bends and focuses light.","x":1,"s":1},{"c":13,"t":"Hair Follicle","d":"The small sac in the skin that holds the root of a hair.","x":1,"s":1},{"c":13,"t":"Malocclusion","d":"When the upper and lower teeth don't line up correctly (a misaligned bite).","x":1,"s":1},{"c":14,"t":"Cartilage","d":"Strong, flexible connective tissue that cushions joints and forms soft structures like the nose and ears.","x":0,"s":1},{"c":14,"t":"Ossification","d":"The process by which cartilage is converted into bone during development.","x":0,"s":1},{"c":14,"t":"Ligament","d":"A band of fibrous connective tissue that connects bone to bone at a joint.","x":0,"s":1},{"c":14,"t":"Tendon","d":"A fibrous cord that connects muscle to bone.","x":0,"s":1},{"c":14,"t":"Scoliosis","d":"An abnormal lateral (side-to-side) curvature of the spine.","x":0,"s":1},{"c":14,"t":"Osteoporosis","d":"A condition of progressive bone tissue loss that makes bones weak and fracture-prone.","x":0,"s":1},{"c":14,"t":"Skeletal muscles","d":"Muscles attached to bones that produce voluntary body movements.","x":0,"s":1},{"c":14,"t":"Cardiac muscle","d":"The involuntary striated muscle that forms the walls of the heart — beats ~100,000 times/day.","x":0,"s":1},{"c":14,"t":"Tendinitis","d":"Inflammation of a tendon, usually from overuse or injury.","x":0,"s":1},{"c":14,"t":"Neurons","d":"Nerve cells that transmit messages to and from the brain and spinal cord.","x":0,"s":1},{"c":14,"t":"Cerebrum","d":"The largest part of the brain; center of conscious thought, learning, memory, and voluntary movement.","x":0,"s":1},{"c":14,"t":"Cerebellum","d":"The part of the brain that coordinates skeletal muscle movement, balance, and posture.","x":0,"s":1},{"c":14,"t":"Brain stem","d":"The stalk connecting the spinal cord to the rest of the brain; regulates vital involuntary functions.","x":0,"s":1},{"c":14,"t":"Epilepsy","d":"A neurological disorder characterized by recurrent, unpredictable seizures.","x":0,"s":1},{"c":14,"t":"Skeletal system","d":"The framework of 206 bones that supports the body, protects organs, and enables movement.","x":0,"s":1},{"c":14,"t":"Synapse","d":"The gap between neurons where chemical neurotransmitters pass signals.","x":0,"s":1},{"c":14,"t":"Reflex","d":"An automatic, involuntary response to a stimulus, processed in the spinal cord.","x":0,"s":1},{"c":14,"t":"Axial skeleton","d":"The skull, vertebral column and rib cage, which protect the brain, spinal cord and vital organs.","x":0,"s":1},{"c":14,"t":"Appendicular skeleton","d":"The arms, legs, and shoulder and hip girdles, which enable movement.","x":0,"s":1},{"c":14,"t":"Central nervous system","d":"The brain and spinal cord, which process information and send commands.","x":0,"s":1},{"c":14,"t":"Peripheral nervous system","d":"All the nerves outside the brain and spinal cord, which relay signals between the CNS and the body.","x":0,"s":1},{"c":14,"t":"Flexor","d":"A muscle that bends (closes) a joint, like the biceps at the elbow.","x":1,"s":1},{"c":14,"t":"Extensor","d":"A muscle that straightens (opens) a joint, like the triceps at the elbow.","x":1,"s":1},{"c":14,"t":"Hernia","d":"When an organ or tissue pushes through a weak spot in the muscle around it.","x":1,"s":1},{"c":15,"t":"Plasma","d":"The liquid portion of blood (~55%), carrying nutrients, proteins, hormones, and salts.","x":0,"s":1},{"c":15,"t":"Hemoglobin","d":"The oxygen-carrying protein in red blood cells, containing iron.","x":0,"s":1},{"c":15,"t":"Platelets","d":"Blood cell fragments that initiate clotting when a vessel is damaged.","x":0,"s":1},{"c":15,"t":"Capillaries","d":"The smallest blood vessels; the site of gas and nutrient exchange between blood and cells.","x":0,"s":1},{"c":15,"t":"Blood pressure","d":"The force blood exerts against artery walls as the heart pumps — measured in mmHg.","x":0,"s":1},{"c":15,"t":"Diaphragm","d":"The dome-shaped muscle below the lungs that drives breathing.","x":0,"s":1},{"c":15,"t":"Trachea","d":"The windpipe; carries air from the throat to the bronchi.","x":0,"s":1},{"c":15,"t":"Asthma","d":"A chronic inflammatory condition in which airways narrow, causing difficulty breathing.","x":0,"s":1},{"c":15,"t":"Emphysema","d":"A progressive, irreversible disease that destroys alveolar walls; almost always caused by smoking.","x":0,"s":1},{"c":15,"t":"Mastication","d":"The mechanical process of chewing.","x":0,"s":1},{"c":15,"t":"Peristalsis","d":"Rhythmic, involuntary muscle contractions that move food through the digestive tract.","x":0,"s":1},{"c":15,"t":"Nephrons","d":"The microscopic filtering units of the kidney; each kidney has over one million.","x":0,"s":1},{"c":15,"t":"Cardiovascular system","d":"The organ system of the heart and blood vessels that circulates blood throughout the body.","x":0,"s":1},{"c":15,"t":"Artery","d":"A blood vessel that carries oxygenated blood away from the heart.","x":0,"s":1},{"c":15,"t":"Vein","d":"A blood vessel that returns deoxygenated blood back to the heart.","x":0,"s":1},{"c":15,"t":"Alveoli","d":"Tiny air sacs in the lungs where oxygen and carbon dioxide are exchanged.","x":0,"s":1},{"c":15,"t":"Villi","d":"Tiny finger-like projections in the small intestine that absorb nutrients.","x":0,"s":1},{"c":15,"t":"Cholesterol","d":"A fatty substance in the blood; high levels increase risk of heart disease.","x":0,"s":1},{"c":15,"t":"Hypertension","d":"Persistently high blood pressure; a major risk factor for heart attack and stroke.","x":0,"s":1},{"c":15,"t":"Cilia","d":"Tiny hairs lining the airways that trap and sweep out debris.","x":0,"s":1},{"c":15,"t":"Pathogen","d":"A germ, such as a virus or bacteria, that causes disease.","x":1,"s":1},{"c":15,"t":"Bronchi","d":"The two main air tubes that carry air from the trachea into the lungs.","x":1,"s":1},{"c":15,"t":"Bile","d":"A fluid made by the liver that helps break down fats during digestion.","x":1,"s":1},{"c":16,"t":"Endocrine glands","d":"Ductless organs that release hormones directly into the bloodstream.","x":0,"s":1},{"c":16,"t":"Hormones","d":"Chemical messengers that regulate body functions including growth, metabolism, mood, and reproduction.","x":0,"s":1},{"c":16,"t":"Thyroid gland","d":"Neck gland that produces thyroxine, regulating metabolism, body heat, and bone growth.","x":0,"s":1},{"c":16,"t":"Pancreas","d":"Dual-function organ that regulates blood sugar through insulin (lowers) and glucagon (raises).","x":0,"s":1},{"c":16,"t":"Pituitary gland","d":"The 'master gland' that regulates all other endocrine glands.","x":0,"s":1},{"c":16,"t":"Testosterone","d":"The primary male sex hormone; drives puberty, muscle development, and sperm production.","x":0,"s":1},{"c":16,"t":"Testes","d":"The two male reproductive glands that produce sperm and testosterone.","x":0,"s":0},{"c":16,"t":"Ovaries","d":"The female reproductive glands that store ova and produce estrogen and progesterone.","x":0,"s":0},{"c":16,"t":"Ovulation","d":"The monthly release of a mature egg from an ovary into the fallopian tube.","x":0,"s":0},{"c":16,"t":"Menstruation","d":"The monthly shedding of the uterine lining when pregnancy has not occurred.","x":0,"s":0},{"c":16,"t":"Uterus","d":"The hollow, muscular organ that nourishes and protects a developing fetus during pregnancy.","x":0,"s":0},{"c":16,"t":"Puberty","d":"The biological process by which the body develops adult reproductive and secondary sex characteristics.","x":0,"s":1},{"c":16,"t":"Endocrine system","d":"The system of glands that produce and release hormones into the bloodstream.","x":0,"s":1},{"c":16,"t":"Estrogen","d":"The primary female sex hormone responsible for reproductive development and the menstrual cycle.","x":0,"s":1},{"c":16,"t":"Fertilization","d":"The union of a sperm cell and an egg cell to form a zygote.","x":0,"s":0},{"c":16,"t":"Insulin","d":"A hormone produced by the pancreas that regulates blood sugar levels.","x":0,"s":1},{"c":16,"t":"Adrenal glands","d":"Glands above the kidneys that produce adrenaline and cortisol for stress response.","x":0,"s":1},{"c":16,"t":"Progesterone","d":"A female sex hormone made by the ovaries that helps regulate the menstrual cycle.","x":0,"s":1},{"c":16,"t":"Glucagon","d":"A hormone made by the pancreas that raises blood sugar.","x":0,"s":1},{"c":16,"t":"Menstrual cycle","d":"A roughly 28-day hormone cycle that prepares the uterus for a possible pregnancy.","x":0,"s":0},{"c":16,"t":"Parathyroid Glands","d":"Small glands in the neck that control the calcium level in your blood and bones.","x":1,"s":1},{"c":16,"t":"Fallopian Tubes","d":"The tubes that carry eggs from the ovaries to the uterus.","x":1,"s":0},{"c":16,"t":"Sterility","d":"Not being able to reproduce.","x":1,"s":0}]}];
